# WARNING - Generated by {fusen} from dev/flat_teaching.Rmd: do not edit by hand # nolint: line_length_linter.

#' Select Top or Bottom Percentage of Data
#'
#' @description
#' Selects the top (largest) or bottom (smallest) percentage of data based on
#' specified traits. Positive percentages extract the largest values; negative
#' percentages extract the smallest values.
#'
#' @param data A data.frame or data.table.
#' @param perc A numeric vector strictly between -1 and 1 (excluding 0).
#'   Positive values (e.g., 0.05) select the top X% of largest values.
#'   Negative values (e.g., -0.1) select the bottom X% of smallest values.
#' @param cols Numeric trait column(s) to analyse, as names or indices.
#' @param by Grouping column(s), as names or indices. Default is NULL.
#' @param keep_data Logical. If TRUE, returns a named list where each element
#'   contains both \code{stat} (summary statistics) and \code{data} (the
#'   subset rows). If FALSE (default), returns a single combined data.frame of
#'   statistics for all \code{perc} values.
#' @param stats Statistics of the selected records, computed exactly as in
#'   [desc_stats()] (same names and definitions). Default
#'   \code{c("n", "min", "max", "mean", "median", "sd", "se", "cv")}; any of
#'   \code{"n", "min", "max", "mean", "median", "q1", "q3", "iqr", "mad",
#'   "sd", "se", "ci", "ci_low", "ci_high", "cv", "skew", "kurt"}.
#'
#' @return
#' \itemize{
#'   \item \code{keep_data = FALSE}: a \code{data.frame} with one row per
#'     \code{by} / \code{cols} / \code{perc} combination: the \code{by}
#'     columns, \code{variable}, the requested \code{stats} and
#'     \code{selection}.
#'   \item \code{keep_data = TRUE}: a named list (one element per \code{perc}
#'     value) where each element is a list with \code{$stat} and \code{$data}.
#' }
#'
#' @details
#' Ranking uses \code{ties.method = "min"}, so tied values at the cut-off are
#' all selected and slightly more than the requested share can be returned.
#' Missing values are removed before ranking. Groups with fewer than
#' \code{1 / abs(perc)} non-missing records cannot contribute a single
#' record: they are kept in the summary with \code{n = 0} and a warning is
#' issued.
#'
#' @seealso [desc_stats()] for statistics of all records.
#'
#' @importFrom data.table as.data.table melt frank rbindlist
#' @export
#' @examples
#' # Example 1: Basic usage with single trait
#' # This example selects the top 10% of observations based on Petal.Width
#' # keep_data=TRUE returns both summary statistics and the filtered data
#' top_perc(iris, 
#'          perc = 0.1,                # Select top 10%
#'          cols = c("Petal.Width"),   # Column to analyze
#'          keep_data = TRUE)          # Return both stats and filtered data
#'
#' # Example 2: Using grouping with 'by' parameter
#' # This example performs the same analysis but separately for each Species
#' # Returns a data.frame of summary statistics, one row per Species
#' top_perc(iris, 
#'          perc = 0.1,                # Select top 10%
#'          cols = c("Petal.Width"),   # Column to analyze
#'          by = "Species")            # Group by Species
top_perc <- function(data, perc, cols, by = NULL, keep_data = FALSE,
                     stats = c("n", "min", "max", "mean", "median", "sd", "se", "cv")) {
  value <- selection <- N <- .variable <- .var_ord <- NULL

  # -- 1. Argument validation --------------------------------------------------
  missing_args <- c(if (missing(data)) "data", if (missing(perc)) "perc",
                    if (missing(cols)) "cols")
  if (length(missing_args) > 0L)
    stop("Missing required argument(s): ", paste(missing_args, collapse = ", "),
         call. = FALSE)
  if (!is.data.frame(data))
    stop("`data` must be a data.frame or data.table.", call. = FALSE)
  if (!is.numeric(perc) || length(perc) == 0L || anyNA(perc))
    stop("`perc` must be a non-empty numeric vector with no NA values.", call. = FALSE)
  if (any(perc <= -1 | perc >= 1 | perc == 0))
    stop("Each element of `perc` must be strictly between -1 and 1, and not 0.",
         call. = FALSE)
  if (anyDuplicated(perc)) {
    warning("Duplicated `perc` values were removed.", call. = FALSE)
    perc <- unique(perc)
  }
  .check_flag(keep_data, "keep_data")
  available <- c("n", "min", "max", "mean", "median", "q1", "q3", "iqr", "mad",
                 "sd", "se", "ci", "ci_low", "ci_high", "cv", "skew", "kurt")
  if (!is.character(stats) || !length(stats) || anyNA(stats))
    stop("`stats` must be a character vector of statistic names.", call. = FALSE)
  bad <- setdiff(stats, available)
  if (length(bad))
    stop("Unknown statistic(s) in `stats`: ", paste(bad, collapse = ", "),
         ". Available: ", paste(available, collapse = ", "), call. = FALSE)
  stats <- unique(stats)

  # Read-only below, so a data.table input needs no copy.
  dt <- if (data.table::is.data.table(data)) data else data.table::as.data.table(data)
  trait <- .resolve_cols(cols, names(dt), "cols")
  by    <- .resolve_cols(by, names(dt), "by", allow_null = TRUE)
  overlap <- intersect(trait, by)
  if (length(overlap) > 0L)
    stop("Column(s) appear in both `cols` and `by`: ",
         paste(overlap, collapse = ", "), call. = FALSE)
  non_num <- trait[!vapply(trait, function(cn) is.numeric(dt[[cn]]), logical(1L))]
  if (length(non_num) > 0L)
    stop("`cols` column(s) must be numeric: ", paste(non_num, collapse = ", "),
         call. = FALSE)

  # -- 2. Long format, once ----------------------------------------------------
  # Only the grouping columns are carried along unless the selected rows are
  # requested, which keeps the long table small for wide inputs.
  id_cols <- if (keep_data) setdiff(names(dt), trait) else if (is.null(by)) character(0L) else by
  dt_long <- data.table::melt(
    dt,
    id.vars         = id_cols,
    measure.vars    = trait,
    variable.name   = "variable",
    value.name      = "value",
    variable.factor = FALSE,
    na.rm           = TRUE
  )
  groupby  <- c(by, "variable")
  grp_size <- dt_long[, .N, by = groupby]
  grp_keys <- grp_size[, groupby, with = FALSE]

  # -- 3. One pass per perc value ----------------------------------------------
  results <- lapply(perc, function(p) {
    abs_p <- abs(p)

    # Groups too small for this percentage would select nothing at all.
    small <- grp_size[N * abs_p < 1]
    if (nrow(small) > 0L)
      warning(sprintf(paste0("perc = %s: %d group(s) have fewer than %d non-missing ",
                             "records, so no record is selected (reported with n = 0)."),
                      format(p), nrow(small), ceiling(1 / abs_p)), call. = FALSE)

    idx <- dt_long[, .I[{
      r <- data.table::frank(if (p > 0) -value else value, ties.method = "min")
      r <= .N * abs_p
    }], by = groupby]$V1
    sub_dt <- dt_long[idx]

    # Statistics from the same engine as desc_stats(); every group is kept,
    # including those with no selected record (n = 0).
    stats_dt <- .desc_engine(sub_dt, "value", groupby, stats, groups = grp_keys)
    stats_dt[, c(".variable", ".var_ord") := NULL]

    label <- if (p > 0) sprintf("top_%.4g%%", abs_p * 100)
             else       sprintf("bottom_%.4g%%", abs_p * 100)
    stats_dt[, selection := label]

    if (keep_data) list(stat = as.data.frame(stats_dt), data = as.data.frame(sub_dt))
    else as.data.frame(stats_dt)
  })
  names(results) <- paste0("perc_", perc)

  if (keep_data) results else as.data.frame(data.table::rbindlist(results))
}
